/* Explicit animation parameters only. Keeps body, card identity, stats and celebrations. */
static struct {uptr id,source;} motion_rows[1024];static u32 motion_count;static volatile u32 motion_ready,motion_applies,motion_failures;static volatile uptr motion_last_id,motion_last_source;
__attribute__((visibility("default")))u32 editor_motion_add(uptr id,uptr source){if(motion_ready||!id||!source||id==source||motion_count>=1024)return 0;for(u32 i=0;i<motion_count;i++)if(motion_rows[i].id==id)return 0;motion_rows[motion_count].id=id;motion_rows[motion_count++].source=source;return 1;}
__attribute__((visibility("default")))void editor_motion_commit(void){__atomic_store_n(&motion_ready,1,__ATOMIC_RELEASE);}
__attribute__((visibility("default")))uptr editor_motion_status(u32 i){return i==0?motion_ready:i==1?motion_count:i==2?motion_applies:i==3?motion_failures:i==4?motion_last_id:motion_last_source;}
static void editor_motion_apply(void*p,uptr id){if(!motion_ready||!get_context||!original_player)return;for(u32 i=0;i<motion_count;i++)if(motion_rows[i].id==id){uptr source=motion_rows[i].source,chain[16];u32 chain_n=0;for(u32 depth=0;depth<16;depth++){chain[chain_n++]=source;uptr next=0;for(u32 k=0;k<motion_count;k++)if(motion_rows[k].id==source)next=motion_rows[k].source;if(!next)break;if(next==id||depth==15){motion_failures++;return;}source=next;}
 unsigned char*ctx=get_context();void*db=ctx?*(void**)(ctx+0x40):0;if(!db){motion_failures++;return;}PlayerKey key={0,source};void*donor=original_player(db,key);if(!valid_player(donor,source)){motion_failures++;return;}u32 v[8];for(u32 k=0;k<8;k++)if(!get_parameter(donor,51+k,&v[k])){motion_failures++;return;}
 /* Source's explicit native motion edits have precedence over its database defaults. */
 u32 cid=active_competition;for(u32 step=chain_n;step>0;step--)for(u32 pass=0;pass<2;pass++)for(u32 z=0;z<editor_np;z++){EditorPlayer*r=&editor_players[z];if(r->id==chain[step-1]&&editor_player_scope(r,cid)&&((!pass&&!r->cid)||(pass&&cid&&r->cid==cid)))for(u32 k=0;k<8;k++)if(r->present[51+k])v[k]=r->value[51+k];}
 for(u32 k=0;k<8;k++)if(!set_parameter(p,51+k,v[k])){motion_failures++;return;}motion_last_id=id;motion_last_source=source;motion_applies++;return;}}
